from datetime import datetime, timedelta

def add_business_days(start, n, holidays):
    # validate n
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    # validate start format
    try:
        dt = datetime.strptime(start, "%Y-%m-%d")
    except Exception:
        raise ValueError("start must be YYYY-MM-DD")
    # parse holidays set
    hol_set = set()
    for h in holidays:
        try:
            hol_dt = datetime.strptime(h, "%Y-%m-%d")
        except Exception:
            raise ValueError(f"holiday {h} must be YYYY-MM-DD")
        hol_set.add(hol_dt.date())
    if n == 0:
        return start
    current = dt.date()
    count = 0
    while count < n:
        current += timedelta(days=1)
        if current.weekday() < 5 and current not in hol_set:
            count += 1
    return current.isoformat()

